{
  "themes": [
    {
      "cluster": 0,
      "name": "Battery Drain & Wi‑Fi Glitches After iOS Update",
      "description": "Customers report severe battery loss, Wi‑Fi constantly reconnecting, and apps crashing after upgrading to iOS 11."
    },
    {
      "cluster": 1,
      "name": "Missing Auto‑Brightness Toggle",
      "description": "Users are upset that iOS 11 removed the manual control for screen brightness and want a way to disable automatic adjustments."
    },
    {
      "cluster": 2,
      "name": "Apple Watch Update & Compatibility Issues",
      "description": "Feedback highlights watchOS update failures, charger incompatibility, and questions about accessory material consistency."
    },
    {
      "cluster": 3,
      "name": "FaceTime Call Routing & Group Call Requests",
      "description": "Customers experience calls going to the wrong contact, FaceTime not working on macOS, and are asking for group FaceTime functionality."
    },
    {
      "cluster": 4,
      "name": "Maps GPS Inaccuracy and Search Failures",
      "description": "Users report that location data is wrong, GPS drops out while driving, and map searches return no results after the iOS 11 upgrade."
    },
    {
      "cluster": 5,
      "name": "Siri Voice Changes and Feature Regression",
      "description": "Feedback complains about the new Siri voice, loss of song‑identification, and overall reduced usefulness for accessibility."
    },
    {
      "cluster": 6,
      "name": "iBooks/Pages PDF & ePub Opening Problems",
      "description": "Customers cannot download, open, or view PDF and ePub files in iBooks or Pages after updating to iOS 11."
    },
    {
      "cluster": 7,
      "name": "MacBook & iMac Unexpected Shutdowns and Noise",
      "description": "Users describe random power‑off events, high‑pitched whining noises, and general instability on newer Mac hardware."
    },
    {
      "cluster": 8,
      "name": "Wi‑Fi & Bluetooth Auto‑Connect Issues",
      "description": "Feedback mentions Wi‑Fi lag, hotspot location confusion, and Bluetooth turning on/off by itself after the iOS 11 update."
    },
    {
      "cluster": 9,
      "name": "Phishing & Scam Email Reports",
      "description": "Customers are receiving fraudulent emails and texts impersonating Apple and request help identifying and stopping them."
    },
    {
      "cluster": 10,
      "name": "Screen Recording Freezes and Video Playback Errors",
      "description": "Users experience screen recordings that capture only audio or freeze, and cannot play back HEVC videos on macOS."
    },
    {
      "cluster": 11,
      "name": "Apple TV Color Conversion & Remote Pairing Problems",
      "description": "Feedback complains about unwanted HDR color conversion, HDMI compatibility questions, and remote control pairing issues with Apple TV."
    }
  ]
}
